(function(){
  if (window.__faradayInstalled__) return;
  window.__faradayInstalled__ = true;
  var canvas = document.getElementById('cv');
  var ctx = canvas.getContext('2d');
  var vSlider = document.getElementById('vSlider'), vVal = document.getElementById('vVal');
  var nSlider = document.getElementById('nSlider'), nVal = document.getElementById('nVal');
  var out = document.getElementById('out');
  var playBtn = document.getElementById('playBtn');
  var running = true, t = 0, prevPhi = null;
  var S = 0.01, k = 2e-5;
  var phiHist = [], eHist = [];
  window.simState = { v: 1, N: 100, phiMax: 0, eMax: 0, running: true };
  function draw(){
    var v = parseFloat(vSlider.value), N = parseFloat(nSlider.value);
    if (running) t += 0.03 * v;
    var p = 0.07 + 0.03 * Math.sin(t);
    var B = k / (p * p);
    var phi = N * B * S;
    var e = 0;
    if (prevPhi !== null) e = -(phi - prevPhi) / (0.03 * v);
    prevPhi = phi;
    window.simState.v = v; window.simState.N = N;
    window.simState.phi = phi; window.simState.e = e;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#94a3b8'; ctx.lineWidth = 1; ctx.strokeRect(0.5, 0.5, canvas.width - 1, canvas.height - 1);
    var cx = 150, cy = 180;
    ctx.strokeStyle = '#475569'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(cx - 95, cy - 85); ctx.lineTo(cx - 95, cy + 85);
    ctx.moveTo(cx + 95, cy - 85); ctx.lineTo(cx + 95, cy + 85); ctx.stroke();
    ctx.strokeStyle = '#1d4ed8'; ctx.lineWidth = 2;
    for (var q = -3; q <= 3; q++) {
      var tq = q / 4;
      ctx.beginPath(); ctx.arc(cx + 95 * tq, cy, 22 * (1 - Math.abs(tq)), 0, Math.PI * 2); ctx.stroke();
    }
    ctx.fillStyle = '#0f172a'; ctx.font = 'bold 13px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('وشيعة (N حلقات)', cx + 95, cy + 105);
    var mx = cx + 95 + 130 * Math.sin(t) - 95;
    var mxl = mx - 34, mxr = mx + 34;
    ctx.fillStyle = '#dc2626'; ctx.fillRect(mxr, cy - 30, 34, 60);
    ctx.fillStyle = '#2563eb'; ctx.fillRect(mxl, cy - 30, 34, 60);
    ctx.fillStyle = '#fff'; ctx.font = 'bold 14px sans-serif';
    ctx.fillText('S', mxr + 17, cy + 5); ctx.fillText('N', mxl + 17, cy + 5);
    ctx.fillStyle = '#0f172a'; ctx.font = '12px sans-serif';
    ctx.fillText('مغناطيس', mx, cy + 48);
    var gx = 700, gy = 100;
    ctx.strokeStyle = '#475569'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(gx, gy, 40, 0, Math.PI); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(gx - 40, gy); ctx.lineTo(gx + 40, gy); ctx.stroke();
    ctx.fillStyle = '#334155'; ctx.font = 'bold 13px sans-serif';
    ctx.fillText('جلفانومتر', gx, gy - 52);
    var def = Math.max(-1, Math.min(1, e / 0.015));
    ctx.strokeStyle = '#dc2626'; ctx.lineWidth = 3;
    ctx.beginPath(); ctx.moveTo(gx, gy); ctx.lineTo(gx - def * 34, gy - 30); ctx.stroke();
    var phx0 = 430, phy0 = 330, phw = 280, phh = 220, px = phx0;
    phiHist.push([px, phy0 - (phi / 0.015) * 140]);
    eHist.push([px, 220 - (e / 0.015) * 90]);
    if (phiHist.length > phw) { phiHist.shift(); eHist.shift(); }
    ctx.strokeStyle = '#e2e8f0'; ctx.lineWidth = 1;
    for (var i = 0; i <= phw; i += 40) { ctx.beginPath(); ctx.moveTo(phx0 + i, 120); ctx.lineTo(phx0 + i, phy0); ctx.stroke(); }
    for (var j = 0; j <= 4; j++) { ctx.beginPath(); ctx.moveTo(phx0, 120 + j * 52.5); ctx.lineTo(phx0 + phw, 120 + j * 52.5); ctx.stroke(); }
    ctx.fillStyle = '#15803d'; ctx.font = 'bold 12px sans-serif'; ctx.textAlign = 'center';
    ctx.fillText('Φ(t)', phx0 + 30, 116);
    ctx.fillStyle = '#b91c1c'; ctx.fillText('e(t)', phx0 + 80, 116);
    ctx.strokeStyle = '#15803d'; ctx.lineWidth = 2;
    ctx.beginPath();
    for (var h = 0; h < phiHist.length; h++) { if (h === 0) ctx.moveTo(phiHist[h][0], phiHist[h][1]); else ctx.lineTo(phiHist[h][0], phiHist[h][1]); }
    ctx.stroke();
    ctx.strokeStyle = '#b91c1c'; ctx.lineWidth = 2;
    ctx.beginPath();
    for (var h2 = 0; h2 < eHist.length; h2++) { if (h2 === 0) ctx.moveTo(eHist[h2][0], eHist[h2][1]); else ctx.lineTo(eHist[h2][0], eHist[h2][1]); }
    ctx.stroke();
    var phiMax = 0, eAbsMax = 0;
    for (var m = 0; m < phiHist.length; m++) { var d = Math.abs(phiHist[m][1] - phy0); if (d > phiMax) phiMax = d; }
    for (var m2 = 0; m2 < eHist.length; m2++) { var d2 = Math.abs(eHist[m2][1] - 220); if (d2 > eAbsMax) eAbsMax = d2; }
    window.simState.phiMax = phiMax / 140 * 0.015;
    window.simState.eMax = eAbsMax / 90 * 0.015;
    vVal.textContent = v.toFixed(1); nVal.textContent = N.toFixed(0);
    out.textContent = 'Φmax ≈ ' + (window.simState.phiMax * 1000).toFixed(1) + ' mWb | |e|max ≈ ' + (window.simState.eMax * 1000).toFixed(1) + ' mV | الوشيعة تعارض تغير التدفق (قانون لنز)';
    window.simState.time = t;
  }
  function loop(){ draw(); requestAnimationFrame(loop); }
  playBtn.addEventListener('click', function(){ running = !running; window.simState.running = running; playBtn.textContent = running ? 'إيقاف الحركة' : 'تشغيل الحركة'; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
